mapper.update:
MERGE INTO SYX0HY target
USING DUAL
   ON (target.GIJUN_YMD = #{gijunYmd}
   AND target.CURRENCY = #{currency})
WHEN MATCHED THEN
    UPDATE SET target.GIJUN_RT = #{gijunRt, jdbcType=NUMERIC}
             , target.TRANS_RT = #{transRt, jdbcType=NUMERIC}
             , target.CROSS_RATE = #{crossRate, jdbcType=NUMERIC}
             , target.CROSS_CURRENCY = #{crossCurrency, jdbcType=VARCHAR}
             , target.IP_YMD = SYSDATE
WHEN NOT MATCHED THEN
    INSERT (
        GIJUN_YMD
      , CURRENCY
      , GIJUN_RT
      , TRANS_RT
      , IP_YMD
      , CROSS_RATE
      , CROSS_CURRENCY
    )
    VALUES (
        #{gijunYmd}
      , #{currency}
      , #{gijunRt, jdbcType=NUMERIC}
      , #{transRt, jdbcType=NUMERIC}
      , SYSDATE
      , #{crossRate, jdbcType=NUMERIC}
      , #{crossCurrency, jdbcType=VARCHAR}
    )

mapper.delete:
DELETE FROM SYX0HY
 WHERE GIJUN_YMD = #{ymd}
   AND CURRENCY = #{currency}
